<?php
namespace App\Http\Controllers;
use App\Models\Transaksi; use Illuminate\Http\Request;
class InvoiceController extends Controller { public function show(Request $r,Transaksi $transaksi){abort_unless(in_array($transaksi->jenis_transaksi,['servis','cuci_mobil','penjualan_sparepart'],true),404);if($r->user()->roleName()==='pelanggan')abort_unless($transaksi->id_pelanggan!==null && (int)$transaksi->id_pelanggan===(int)$r->user()->pelanggan?->id_pelanggan,403);$transaksi->load(['pelanggan','petugas','pembayarans']);$paid=$transaksi->pembayarans->where('arah','masuk')->where('status','terverifikasi')->sum('jumlah');if($transaksi->jenis_transaksi==='servis'){$transaksi->load(['servis.kendaraan','servis.bookingServis','servis.details','servis.sparepartItems.sparepart']);return view('invoices.servis',compact('transaksi','paid'));}if($transaksi->jenis_transaksi==='cuci_mobil'){$transaksi->load(['bookingCuci.kendaraan','bookingCuci.paket']);return view('invoices.carwash',compact('transaksi','paid'));}$transaksi->load(['penjualanSparepart.details.sparepart']);return view('invoices.sparepart',compact('transaksi','paid'));} }
